import {materialIcon} from './material-pixel-art.js';
import {RECIPES,POTIONS,MATERIALS,RARITY,recipeKnown,eligiblePotionRecipeMaterials} from './engine.js';
import {icon} from './icons.js';
import {potionDescription} from './potion-ui.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderPotionRecipePicker(s,selected){return `<div class="potionTypeChoices" aria-label="固定药剂配方">${Object.values(RECIPES).filter(r=>r.enabled).map(r=>`<button data-potion-recipe="${r.id}" aria-pressed="${selected===r.id}" title="${esc(recipeKnown(s,r.id)?'已掌握':'尚未掌握')}">${icon(r.icon)}${esc(POTIONS[r.potionType].name)}${recipeKnown(s,r.id)?'':' · 未学'}</button>`).join('')}</div>`;}
export function renderPotionRecipe(s,{id,quality=0,mainKey='',auxKey='',quantity=1,quote=null,error='',busy=false}={}){const r=RECIPES[id];if(!r)return '';const p=POTIONS[r.potionType],known=recipeKnown(s,id),cost=r.craftGoldByQuality[quality]*quantity;const role=(key,label,chosen)=>`<div class="recoveryMaterial"><strong>${label}</strong>${(()=>{const row=eligiblePotionRecipeMaterials(s,id,key,quality).find(m=>m.key===chosen);return row?materialIcon(row.material,{quality,size:48}):'';})()}<select data-potion-ingredient="${key}" aria-label="${label}" ${busy?'disabled':''}><option value="">选择同品质${label}</option>${eligiblePotionRecipeMaterials(s,id,key,quality).map(m=>`<option value="${esc(m.key)}" ${m.key===chosen?'selected':''}>${esc(MATERIALS[m.material]?.name??m.material)} · 库存 ${m.count}</option>`).join('')}</select></div>`;const issue=error||(cost>s.gold?'金币不足':mainKey&&auxKey&&!quote?'材料不足或数量无效（同一种材料兼任主辅时消耗两份）':'');return `<section class="recoveryRecipe"><div class="recoveryHeading">${icon(p.icon)}<h2>${esc(p.name)} · 固定配方</h2></div>${!known?'<div class="recoveryLocked"><h3>尚未掌握</h3><p>购买配方卷轴后永久掌握。</p><button data-view="merchant">前往行商</button></div>':`<div class="recoveryQuality">${RARITY.slice(0,4).map((n,q)=>`<button class="r${q}text" data-potion-recipe-quality="${q}" aria-pressed="${q===quality}" ${busy?'disabled':''}>${n}</button>`).join('')}</div><div class="recoveryResult potionQ${quality}">${icon(p.icon)}<div><strong>${esc(p.name)} ×${quantity}</strong><small>${esc(potionDescription(r.potionType,quality))}</small></div><b>${cost} ◈</b></div>${role('main','主材料',mainKey)}${role('aux','辅助材料',auxKey)}<label class="recoveryQuantity">制作数量 <input type="number" min="1" max="999" value="${quantity}" data-potion-batch="1" ${busy?'disabled':''}></label>${issue?`<p class="recoveryError" role="alert">${esc(issue)}</p>`:''}<button class="primary" data-potion-recipe-commit="1" ${busy||!quote?'disabled':''}>确认制作 ${quantity} 瓶 · ${cost}◈</button><p class="recoveryNote">每瓶各消耗一份同品质主材料与辅助材料；同一种材料兼任两者时扣两份。固定品质，不触发神赐。最多999瓶，满包成品待领取。</p>`}</section>`;}
